//! `levels/ffa_small.lvl` (HALF = 44, the demo default), generated by `scripts/gen_small_level.py`: the small free-for-all
//! arena. Pinned: it stays small and uncluttered (few boxes), spawns are clear, grounded and spread so fights start within
//! seconds, pickups are supported, the void edges are open, and the geometry fits the engine's numeric limits.

use shinobi_sim::character::{Cfg, PhysicsWorld};
use shinobi_sim::level::{parse_level_file, LevelBox, LevelFile};
use shinobi_sim::rapier3d::prelude::*;
use shinobi_sim::spawn::far_dist;

const HALF: f32 = 44.0;

fn load() -> LevelFile {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa_small.lvl");
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    parse_level_file(&text).unwrap_or_else(|e| panic!("ffa_small.lvl: {e}"))
}

fn world(l: &LevelFile) -> PhysicsWorld {
    let mut w = PhysicsWorld { bodies: RigidBodySet::new(), colliders: ColliderSet::new(), islands: IslandManager::new(), queries: QueryPipeline::new() };
    l.level.insert_into(&mut w);
    w.queries.update(&w.colliders);
    w
}

fn inside(b: &LevelBox, p: [f32; 3]) -> bool {
    let (s, c) = b.rot_z.sin_cos();
    let (dx, dy) = (p[0] - b.center[0], p[1] - b.center[1]);
    let (u, v) = (dx * c + dy * s, -dx * s + dy * c);
    u.abs() <= b.half[0] && v.abs() <= b.half[1] && (p[2] - b.center[2]).abs() <= b.half[2]
}

fn top_at(b: &LevelBox, x: f32, z: f32) -> Option<f32> {
    if (z - b.center[2]).abs() > b.half[2] {
        return None;
    }
    let (s, c) = b.rot_z.sin_cos();
    let u = (x - b.center[0] + b.half[1] * s) / c;
    (u.abs() <= b.half[0]).then(|| b.center[1] + u * s + b.half[1] * c)
}

fn d2(a: [f32; 3], b: [f32; 3]) -> f32 {
    ((a[0] - b[0]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

#[test]
fn small_and_uncluttered_with_a_spawn_ring_and_sparse_pickups() {
    let l = load();
    assert!(l.level.boxes.len() <= 80, "{} boxes: the map must stay uncluttered", l.level.boxes.len());
    assert!(l.level.boxes.len() >= 12, "{} boxes: too empty to play on", l.level.boxes.len());
    assert!((8..=12).contains(&l.level.spawns.len()), "{} spawns", l.level.spawns.len());
    assert!((2..=6).contains(&l.pickups.len()), "{} pickups: sparse", l.pickups.len());
    assert!(l.pickups.iter().all(|p| p.respawn_secs >= 10.0));
}

#[test]
fn spawns_stand_on_solid_ground_clear_of_geometry_and_not_stacked() {
    let l = load();
    let cfg = Cfg::default();
    let reach = cfg.half_height + cfg.radius;
    for s in &l.level.spawns {
        for dy in [-reach + 0.05, -0.3, 0.0, 0.3, reach - 0.05] {
            for (ox, oz) in [(0.0, 0.0), (cfg.radius, 0.0), (-cfg.radius, 0.0), (0.0, cfg.radius), (0.0, -cfg.radius)] {
                let p = [s[0] + ox, s[1] + dy, s[2] + oz];
                assert!(!l.level.boxes.iter().any(|b| inside(b, p)), "spawn {s:?}: capsule point {p:?} is inside geometry");
            }
        }
        let ground = l.level.boxes.iter().filter_map(|b| top_at(b, s[0], s[2])).filter(|h| (h - (s[1] - reach)).abs() < 0.1).count();
        assert!(ground > 0, "spawn {s:?} floats");
        assert!(s[0].abs() < HALF - 8.0 && s[2].abs() < HALF - 8.0, "spawn {s:?} is on the void edge");
    }
    let n = l.level.spawns.len();
    let nearest: Vec<f32> = (0..n).map(|i| (0..n).filter(|j| *j != i).map(|j| d2(l.level.spawns[i], l.level.spawns[j])).fold(f32::MAX, f32::min)).collect();
    let min = nearest.iter().copied().fold(f32::MAX, f32::min);
    assert!(min >= 13.0, "two spawns only {min:.1} m apart");
    // contact within seconds: at a 9 m/s run every spawn has a neighbour inside ~4 s
    let max = nearest.iter().copied().fold(0.0, f32::max);
    assert!(max <= 36.0, "a spawn is {max:.1} m from its nearest neighbour: players would wander alone");
}

#[test]
fn respawn_distance_preference_scales_to_the_map() {
    let l = load();
    let far = far_dist(&l.level.spawns);
    assert!((20.0..=40.0).contains(&far), "preferred respawn distance {far:.1} m on the 88 m arena");
    let big = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../levels/ffa.lvl");
    let big = parse_level_file(&std::fs::read_to_string(big).unwrap()).unwrap();
    assert_eq!(far_dist(&big.level.spawns), 60.0, "the 224 m map keeps the 60 m rule");
}

#[test]
fn pickups_are_supported_and_not_inside_geometry() {
    let l = load();
    for p in &l.pickups {
        assert!(!l.level.boxes.iter().any(|b| inside(b, p.pos)), "pickup {:?} is inside geometry", p.pos);
        let support = l.level.boxes.iter().filter_map(|b| top_at(b, p.pos[0], p.pos[2])).any(|h| (p.pos[1] - h - 1.0).abs() < 0.3);
        assert!(support, "pickup {:?} is not ~1 m above a surface", p.pos);
    }
}

#[test]
fn the_floor_covers_the_map_and_the_void_edges_are_open() {
    let l = load();
    let any = |p: [f32; 3]| l.level.boxes.iter().any(|b| inside(b, p));
    let mut x = -HALF + 0.5;
    while x < HALF {
        let mut z = -HALF + 0.5;
        while z < HALF {
            assert!(any([x, -0.25, z]), "floor gap at ({x}, {z})");
            z += 2.0;
        }
        x += 2.0;
    }
    for p in [[HALF + 3.0, 0.5, 0.0], [-HALF - 3.0, 0.5, 0.0], [0.0, 0.5, HALF + 3.0], [0.0, 0.5, -HALF - 3.0]] {
        assert!(!any(p), "something stands outside the void edge at {p:?}");
    }
    for k in 0..4 {
        let open = (-(HALF as i32)..HALF as i32).step_by(2).filter(|i| {
            let t = *i as f32 + 0.5;
            let p = match k {
                0 => [t, 0.5, -HALF + 0.25],
                1 => [t, 0.5, HALF - 0.25],
                2 => [-HALF + 0.25, 0.5, t],
                _ => [HALF - 0.25, 0.5, t],
            };
            !any(p)
        }).count();
        assert!(open >= 4, "side {k} has only {open} open void cells");
    }
}

#[test]
fn engine_numeric_limits_cover_the_map() {
    let l = load();
    let top = l.level.boxes.iter().map(|b| b.center[1] + b.half[1]).fold(0.0, f32::max);
    let far = l.level.boxes.iter().map(|b| b.center[0].abs() + b.half[0]).chain(l.level.boxes.iter().map(|b| b.center[2].abs() + b.half[2])).fold(0.0, f32::max);
    assert!(far <= HALF + 1.0, "geometry reaches {far} m");
    assert!(top <= 30.0, "tallest geometry {top} m");
    let q = shinobi_proto::quant::q_pos3([2.0 * HALF, top, 2.0 * HALF]);
    let back = shinobi_proto::quant::dq_pos3(q);
    assert!((back[0] - 2.0 * HALF).abs() < 0.01 && (back[2] - 2.0 * HALF).abs() < 0.01, "q_pos3 loses precision");
    let _ = world(&l); // every box becomes a collider
}

#[test]
fn the_hub_and_the_wall_run_lanes_are_where_the_design_says() {
    // a spot on each hub tier, on the pylon top, and inside each wall-run lane (5.6 m between the faces)
    let l = load();
    let solid = |p: [f32; 3]| l.level.boxes.iter().any(|b| inside(b, p));
    for p in [[0.0, 1.0, 5.0], [0.0, 2.0, 3.0], [0.0, 3.3, 1.0], [0.0, 12.5, 0.0]] {
        assert!(solid(p), "hub should be solid at {p:?}");
    }
    for (x, z) in [(-24.0, -28.0), (-24.0, -34.6), (24.0, 28.0), (24.0, 34.6)] {
        assert!(solid([x, 4.0, z]), "lane wall missing at ({x}, {z})");
    }
    assert!(!solid([-24.0, 4.0, -31.3]) && !solid([24.0, 4.0, 31.3]), "the lanes must be open between the walls");
}
